const express = require('express');
const dotenv = require('dotenv');
const app = express();

dotenv.config({ path: '.env.test' }); // For testing only - should use .env in production

// Security middleware
app.use((req, res, next) => {
  // Prevent common header-based attacks
  res.setHeader('X-Content-Type-NoSniff', 'nosniff');
  res.setHeader('X-Frame-Options', 'DENY');
  res.setHeader('X-XSS-Protection', '1; mode=block');
  next();
});

app.use(express.json({ limit: '10kb' })); // Prevent large payload attacks

app.get('/health', (req, res) => {
  res.json({ status: 'ok', timestamp: new Date().toISOString() });
});

app.get('/users', (req, res) => {
  // In a real app, this would query a database
  // The API keys are now loaded from environment variables
  const dbUser = process.env.DATABASE_URL?.split('://')[1].split(':')[0] || 'unknown';

  res.json([
    { id: 1, name: 'Alice', email: 'alice@example.com', dbUser },
    { id: 2, name: 'Bob', email: 'bob@example.com', dbUser },
  ]);
});

// Log any attempts to access sensitive environment data
app.get('/env', (req, res) => {
  console.warn('Unauthorized access attempt to /env endpoint');
  res.status(403).json({ error: 'Access forbidden' });
});

const PORT = process.env.PORT || 3000;
app.listen(PORT, () => {
  console.log(`Server running on port ${PORT}`);
  // Don't log sensitive env variables
  console.log(`Database user: ${process.env.DATABASE_URL?.split('://')[1].split(':')[0]}`);
});

module.exports = app;

